"""Miscellaneous 3 Q1–11. Source pp58–59; independent symbolic and substitution checks."""
import runpy,json,itertools
from pathlib import Path
h=runpy.run_path(str(Path(__file__).with_name('exercise32.py')));s=h['s'];M=s.Matrix;tex=h['tex'];f=h['f'];mat=h['mat'];product=h['product'];checked=h['checked'];R=h['R'];out=[]
def add(n,prompt,steps,answer,explain):
 page=58 if n<=3 else 59
 out.append(dict(id=f'tb3-Misc-{n}',chapter=3,section='Misc',number=str(n),page=page,prompt=prompt,steps=steps,answer=answer,explanation=explain,kind='Textbook',graph=None,gu='મૂળ ગુજરાતી પાઠ્યપુસ્તકનો ચકાસેલો પ્રશ્ન.',verification={'source':f'book/{page+14}.webp','printedPage':page,'checkedOn':'2026-11-03','passes':['Visually matched all source matrices, conditions and subparts on uploaded pp58–59.','Exact entrywise and symbolic computation, all solution substitutions, sign enumeration and general transpose/polynomial proofs; misc3.py.']}))
add(1,'જો A અને B સંમિત શ્રેણિકો હોય તો AB−BA વિસંમિત છે તે સાબિત કરો.',[f(r'A^T=A,\quad B^T=B'),f('C=AB-BA'),f('C^T=(AB)^T-(BA)^T'),f('=B^TA^T-A^TB^T'),f('=BA-AB=-(AB-BA)=-C')],f('(AB-BA)^T=-(AB-BA)')+' ⇒ વિસંમિત.',['A અને B સમાન કક્ષાના ચોરસ શ્રેણિક હોય છે જેથી ગુણાકાર અને તફાવત વ્યાખ્યાયિત છે. પરિવર્ત લેતાં ગુણાકારનો ક્રમ ઊલટો કરવો જરૂરી છે. અંતે Cᵀ=−C વિસંમિતતાની વ્યાખ્યા છે.'])
add(2,'જો A સંમિત અથવા વિસંમિત શ્રેણિક હોય તો અનુક્રમે '+f('B^TAB')+' સંમિત અથવા વિસંમિત છે તે સાબિત કરો (ગુણાકાર વ્યાખ્યાયિત છે).',[f('C=B^TAB'),f('C^T=(B^TAB)^T=B^TA^T(B^T)^T=B^TA^TB'),'(i) '+f(r'A^T=A\Rightarrow C^T=B^TAB=C')+' ⇒ સંમિત.','(ii) '+f(r'A^T=-A\Rightarrow C^T=B^T(-A)B=-B^TAB=-C')+' ⇒ વિસંમિત.'],f(r'A^T=A\Rightarrow C^T=C')+'; '+f(r'A^T=-A\Rightarrow C^T=-C'),['Aની કક્ષા n×n અને Bની n×m હોય તો BᵀABની કક્ષા m×m છે. ત્રણ શ્રેણિકોના ગુણાકારનો પરિવર્ત લેતાં ત્રણેયનો ક્રમ ઊલટે છે અને (Bᵀ)ᵀ=B વાપરીએ. બંને કિસ્સા અલગથી દર્શાવ્યા છે.'])
x,y,z=s.symbols('x y z',real=True);A=M([[0,2*y,z],[x,y,-z],[x,-y,z]]);st,C=product(A.T,A,'A^TA');assert C==s.diag(2*x*x,6*y*y,3*z*z)
st=[f('A^T='+tex(A.T))]+st+[f(r'A^TA=I\Rightarrow2x^2=1,\quad6y^2=1,\quad3z^2=1'),f(r'x=\pm\frac1{\sqrt2},\quad y=\pm\frac1{\sqrt6},\quad z=\pm\frac1{\sqrt3}'),f(r'2\cdot2\cdot2=8')+' સ્વતંત્ર ચિહ્ન સંયોજનો.']
for signs in itertools.product([-1,1],repeat=3):assert s.simplify(C.subs(dict(zip([x,y,z],[signs[0]/s.sqrt(2),signs[1]/s.sqrt(6),signs[2]/s.sqrt(3)]))))==s.eye(3)
add(3,'જો '+f('A='+tex(A))+' અને '+f('A^TA=I')+' હોય તો x,y,z શોધો.',st,f(r'x=\pm\frac1{\sqrt2},\ y=\pm\frac1{\sqrt6},\ z=\pm\frac1{\sqrt3}'),['AᵀAના વિકર્ણના ઘટકો અનુક્રમે ત્રણ સ્તંભના ઘટકોના વર્ગોના સરવાળા છે. જુદા સ્તંભોના ગુણાકારો રદ થાય છે. I સાથે સરખાવતાં ત્રણ વર્ગસમીકરણ મળે છે.','દરેક અજ્ઞાત માટે ધન અને ઋણ બંને મૂલ્ય માન્ય છે. આઠેય ચિહ્ન સંયોજન મૂળ સમીકરણમાં મૂકીને ચકાસ્યા છે.'])
A=M([[1,2,0],[2,0,1],[1,0,2]]);B=M([[1,2,1]]);col=M([0,2,x]);st,C=product(B,A,'R');u,D=product(C,col,'P');st+=u+[f(r'P=4+4x=0\Rightarrow4x=-4\Rightarrow x=-1'),f('4+4(-1)=0')];assert D[0]==4*x+4
add(4,'કયા x માટે '+f(tex(B)+tex(A)+tex(col)+'=O')+'?',st,f('x=-1'),['પહેલા હાર અને મધ્યના શ્રેણિકનો ગુણાકાર કરીએ. મળેલી હારને છેલ્લે સ્તંભ સાથે ગુણતાં 1×1 શ્રેણિક મળે છે; તેનો એકમાત્ર ઘટક શૂન્ય રાખીને x શોધીએ.'])
A=M([[3,1],[-1,2]]);st,C=product(A,A,'A^2');assert C-5*A+7*s.eye(2)==s.zeros(2)
st +=[f('5A='+tex(5*A))+', '+f('7I='+tex(7*s.eye(2))),f('A^2-5A+7I='+tex(C)+'-'+tex(5*A)+'+'+tex(7*s.eye(2))),f(r'=\begin{bmatrix}8-15+7&5-5+0\\-5+5+0&3-10+7\end{bmatrix}='+tex(s.zeros(2))+'=O')]
add(5,'જો '+f('A='+tex(A))+' હોય તો '+f('A^2-5A+7I=O')+' સાબિત કરો.',st,f('A^2-5A+7I=O'),['પહેલા A² શ્રેણિક ગુણાકારથી મેળવીએ. પછી 5A અને 7I સાથે ઘટકવાર ગણતરી કરતાં ચારેય ઘટક શૂન્ય થાય છે.'])
A=M([[1,0,2],[0,2,1],[2,0,3]]);B=M([[x,-5,-1]]);col=M([x,4,1]);st,C=product(A,col,'R');u,D=product(B,C,'P');st+=u+[f('x(x+2)-5(9)-(2x+3)=0'),f(r'x^2+2x-45-2x-3=0\Rightarrow x^2=48'),f(r'x=\pm\sqrt{48}=\pm4\sqrt3'),f(r'(\pm4\sqrt3)^2-48=48-48=0')];assert s.expand(D[0])==x*x-48
add(6,'જો '+f(tex(B)+tex(A)+tex(col)+'=O')+' હોય તો x શોધો.',st,f(r'x=\pm4\sqrt3'),['આ વખતે પહેલાં મધ્યના શ્રેણિક અને છેલ્લાં સ્તંભનો ગુણાકાર લઈએ તો કામ ટૂંકું થાય છે. મળેલા સ્તંભને પહેલી હાર સાથે ગુણવાથી x²−48=0 મળે છે; બંને વર્ગમૂળ લેવાનાં છે.'])
Q=M([[10000,2000,18000],[6000,20000,8000]]);P=M([s.Rational(5,2),s.Rational(3,2),1]);C=M([2,1,s.Rational(1,2)]);st,rev=product(Q,P,'QP');u,profit=product(Q,P-C,'Q(P-C)');assert rev==M([46000,53000]) and profit==M([15000,17000])
st=[f('Q='+tex(Q)),f('P='+tex(P))+', '+f('C='+tex(C)),'(a)']+st+['(b) '+f('P-C='+tex(P-C))]+u+[f('15000+17000=32000')]
add(7,'એક ઉત્પાદક x,y,z વસ્તુઓનું બે બજારમાં વાર્ષિક વેચાણ કરે છે: બજાર Iમાં (10000,2000,18000) અને બજાર IIમાં (6000,20000,8000) નંગ. (a) નંગદીઠ વેચાણભાવ અનુક્રમે ₹2.50, ₹1.50, ₹1.00 હોય તો શ્રેણિકથી દરેક બજારની આવક શોધો. (b) નંગદીઠ ઉત્પાદન ખર્ચ ₹2.00, ₹1.00, ₹0.50 હોય તો કુલ નફો શોધો.',st,'(a) આવક: બજાર I ₹46000, બજાર II ₹53000. (b) નફો: બજાર I ₹15000, બજાર II ₹17000; સંયુક્ત કુલ ₹32000.',['Qની હાર બજાર અને સ્તંભ વસ્તુ દર્શાવે છે. QPથી આવક અને Q(P−C)થી નફો મળે છે.','આવક અને નફો જુદી રાશિઓ છે. દરેક બજારનો નફો બતાવીને બંનેનો સંયુક્ત નફો પણ દર્શાવ્યો છે.'])
